<script setup>
import RecordPagination from './ui/RecordPagination.vue'
import {usePagination} from '../usePagination.js'
import {computed} from 'vue'
import {useLearning} from '../useLearning.js'
import {artwork,icon} from '../assets.js'
import {buildNextActions} from '../homeLayout.js'
const emit=defineEmits(['new-goal','next','note'])
const {state,openSession}=useLearning()
const spaces=computed(()=>(state.boot?.sessions||[]).filter(s=>(s.title+' '+s.goal).toLowerCase().includes(state.query.trim().toLowerCase())))
const featured=computed(()=>spaces.value.find(s=>s.id===state.current?.id)||spaces.value[0])
const others=computed(()=>spaces.value.filter(s=>s.id!==featured.value?.id))
const next=computed(()=>buildNextActions(state.boot?.sessions,state.boot?.materials,featured.value?.id)[0])
const notes=computed(()=>(state.boot?.notes||[]).slice(0,2))
const date=v=>new Date(v).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})
const {page:otherPage,items:otherRows}=usePagination(others,()=>state.query)
</script>
<template><div class="learning-overview-live"><div v-if="featured" class="learning-overview-grid"><section class="learning-current-card"><div class="section-heading"><h2>正在学习的目标</h2><button class="text-button" @click="emit('new-goal')">新建目标</button></div><div class="learning-current-art" :style="{backgroundImage:`url(${artwork[featured.course_id]||artwork.systems})`}"><span class="course-tag apricot">{{ featured.domain }}</span><h2>{{ featured.title }}</h2><p>{{ featured.goal }}</p></div><footer><div><strong>{{ featured.course_id?featured.completed+' 个单元有独立新题表现':'自选跨学科目标' }}</strong><small>每天 {{ featured.daily_minutes }} 分钟 · {{ date(featured.updated_at) }}</small></div><button class="primary-button" @click="openSession(featured.id)">继续学习 <img :src="icon('arrow-right','white')" alt=""></button></footer></section><aside class="studio-side-card learning-next-card"><h2>适合现在的下一步</h2><template v-if="next"><span class="learning-next-symbol"><img :src="icon(next.icon)" alt=""></span><h3>{{ next.title }}</h3><p>{{ next.detail }}</p><div class="learning-next-reason">{{ next.reason }}</div><button class="secondary-button" @click="emit('next',next)">从这一步继续</button></template></aside></div><div v-else class="studio-empty-soft learning-empty"><img src="/assets/split-elements/elements/notes-notebook.compact.webp" alt=""><h2>{{ state.query?'没有匹配的目标':'把好奇的种子，带进更大的世界。' }}</h2><p>不限学科，先写清楚一个想理解或解决的问题。</p><button class="primary-button" @click="emit('new-goal')">创建学习目标</button></div><div class="learning-secondary-grid"><section class="studio-side-card"><div class="section-heading"><h2>其他学习目标</h2><small>{{ others.length }} 个</small></div><button v-for="space in otherRows" :key="space.id" class="learning-recent-row" @click="openSession(space.id)"><img :src="artwork[space.course_id]||artwork.systems" alt=""><span><strong>{{ space.title }}</strong><small>{{ space.domain }} · {{ date(space.updated_at) }}</small></span><img :src="icon('chevron-right')" alt=""></button><RecordPagination v-model="otherPage" :total="others.length" label="学习目标"/><p v-if="!others.length" class="section-description">专注当前目标，也可以随时开始新的探索。</p></section><section class="studio-side-card learning-note-card"><div class="section-heading"><h2>我的笔记</h2><button class="text-button" @click="emit('note')">写一则</button></div><button v-for="note in notes" :key="note.id" class="learning-note-preview" @click="emit('note',note)"><strong>{{ note.title }}</strong><p>{{ note.text.slice(0,110) }}</p><small>{{ date(note.updated_at) }}</small></button><p v-if="!notes.length">记录一个已经想清楚的解释，或一个还想继续追问的问题。</p></section><section class="learning-inspiration"><img src="/assets/split-elements/elements/knowledge-arch.compact.webp" alt=""><h3>好的提问，<br>是另一种创造。</h3><button class="text-button" @click="emit('new-goal','我想从一个生活中的问题出发，寻找不同学科之间的联系')">写下我的问题</button></section></div></div></template>
